enum InputError: Error { case negative, overflow }
func total(_ price: Int, _ quantity: Int) throws -> Int {
    guard price >= 0 && quantity >= 0 else { throw InputError.negative }
    let result = price.multipliedReportingOverflow(by: quantity)
    guard !result.overflow else { throw InputError.overflow }
    return result.partialValue
}
do {
    print(try total(12, 3))
    print(try total(12, 0))
    _ = try total(12, -1)
} catch InputError.negative {
    print("Invalid input rejected")
} catch {
    print("Unexpected error")
}

