enum RegistrationError: Error {
    case emptyName
    case underage(years: Int)
}
func register(name: String, age: Int) throws -> String {
    guard !name.isEmpty else {
        throw RegistrationError.emptyName
    }
    guard age >= 18 else {
        throw RegistrationError.underage(years: 18 - age)
    }
    return "Welcome, \(name)"
}
do {
    print(try register(name: "Dilnoza", age: 21))
    print(try register(name: "", age: 20))
} catch RegistrationError.emptyName {
    print("Name cannot be empty")
} catch RegistrationError.underage(let missing) {
    print("Need \(missing) more years")
} catch {
    print("Unexpected error")
}
do {
    print(try register(name: "Sara", age: 15))
} catch RegistrationError.underage(let missing) {
    print("Need \(missing) more years")
} catch {
    print("Unexpected error")
}

