struct Task {
    let title: String
    var isDone: Bool
}
var tasks = [
    Task(title: "Learn Swift basics", isDone: true),
    Task(title: "Build a todo list", isDone: false),
    Task(title: "Read a Swift guide", isDone: false)
]
func completeTask(at index: Int, in list: inout [Task]) -> Bool {
    guard index >= 0 && index < list.count else {
        return false
    }
    list[index].isDone = true
    return true
}
func searchTasks(matching query: String, in list: [Task]) -> [Task] {
    return list.filter { $0.title.lowercased().contains(query.lowercased()) }
}
let ok = completeTask(at: 1, in: &tasks)
print("Completed: \(ok)")
for task in searchTasks(matching: "swift", in: tasks) {
    print("- \(task.title) (done: \(task.isDone))")
}
let remaining = tasks.filter { !$0.isDone }.count
print("Remaining: \(remaining)")

