struct Student {
    let name: String
    var score: Int

    var passed: Bool {
        return score >= 60
    }
}
let students = [
    Student(name: "Dilnoza", score: 91),
    Student(name: "Sara", score: 55),
    Student(name: "Alisher", score: 73)
]
let passedNames = students.filter { $0.passed }.map { $0.name }.sorted()
print("Passed: \(passedNames)")
let total = students.reduce(0) { sum, student in sum + student.score }
print("Average score: \(total / students.count)")
for student in students {
    let status = student.passed ? "passed" : "failed"
    print("\(student.name): \(student.score) (\(status))")
}

